 void quran(){boolean tg="tg".equals(LanguageManager.getLanguage(this));LinearLayout r=page(tg?"Қуръон • القرآن":"Коран • القرآن");ScrollView s=new ScrollView(this);LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(16),0,D(16),D(20));g.addView(T(tg?"114 сура • матни арабӣ + тарҷумаи тоҷикӣ":"114 сур • арабский текст + русский перевод",14,Color.rgb(158,178,198),false));String[] n={"Аль-Фатиха","Аль-Бакара","Али Имран","Ан-Ниса","Аль-Маида","Аль-Анам","Аль-Араф","Аль-Анфаль","Ат-Тауба","Юнус","Худ","Юсуф","Ар-Рад","Ибрахим","Аль-Хиджр","Ан-Нахль","Аль-Исра","Аль-Кахф","Марьям","Та Ха","Аль-Анбия","Аль-Хадж","Аль-Муминун","Ан-Нур","Аль-Фуркан","Аш-Шуара","Ан-Намль","Аль-Касас","Аль-Анкабут","Ар-Рум","Лукман","Ас-Саджда","Аль-Ахзаб","Саба","Фатыр","Я Син","Ас-Саффат","Сад","Аз-Зумар","Гафир","Фуссилят","Аш-Шура","Аз-Зухруф","Ад-Духан","Аль-Джасия","Аль-Ахкаф","Мухаммад","Аль-Фатх","Аль-Худжурат","Каф","Аз-Зарият","Ат-Тур","Ан-Наджм","Аль-Камар","Ар-Рахман","Аль-Вакиа","Аль-Хадид","Аль-Муджадила","Аль-Хашр","Аль-Мумтахана","Ас-Сафф","Аль-Джумуа","Аль-Мунафикун","Ат-Тагабун","Ат-Талак","Ат-Тахрим","Аль-Мульк","Аль-Калам","Аль-Хакка","Аль-Мааридж","Нух","Аль-Джинн","Аль-Муззаммиль","Аль-Муддассир","Аль-Кияма","Аль-Инсан","Аль-Мурсалят","Ан-Наба","Ан-Назиаат","Абаса","Ат-Таквир","Аль-Инфитар","Аль-Мутаффифин","Аль-Иншикак","Аль-Бурудж","Ат-Тарик","Аль-Ала","Аль-Гашия","Аль-Фаджр","Аль-Балад","Аш-Шамс","Аль-Лейль","Ад-Духа","Аш-Шарх","Ат-Тин","Аль-Алак","Аль-Кадр","Аль-Баййина","Аз-Зальзала","Аль-Адият","Аль-Кариа","Ат-Такасур","Аль-Аср","Аль-Хумаза","Аль-Филь","Курайш","Аль-Маун","Аль-Каусар","Аль-Кафирун","Ан-Наср","Аль-Масад","Аль-Ихляс","Аль-Фаляк","Ан-Нас"};for(int i=0;i<114;i++){final int no=i+1;MaterialCardView c=card(String.format(Locale.US,"%03d  %s",no,n[i]),"Открыть суру • "+no);c.setOnClickListener(v->surah(no,n[no-1]));add(g,c,72);}s.addView(g);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
 void surah(int no,String name){LinearLayout r=page(name);ProgressBar p=new ProgressBar(this);p.setIndeterminate(true);r.addView(p,new LinearLayout.LayoutParams(-1,D(55)));TextView info=T("Загрузка арабского текста и таджикского перевода…",13,Color.LTGRAY,false);r.addView(info);ScrollView s=new ScrollView(this);LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(16),D(8),D(16),D(30));s.addView(g);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);new Thread(()->{try{boolean tajik="tg".equals(LanguageManager.getLanguage(this));String edition=tajik?"tg.ayati":"ru.kuliev";String key="surah_"+no+"_"+edition;String cached=getPreferences(0).getString(key,null);String json=cached!=null?cached:get("https://api.alquran.cloud/v1/surah/"+no+"/editions/quran-uthmani,"+edition);if(cached==null)getPreferences(0).edit().putString(key,json).apply();JSONObject root=new JSONObject(json);JSONArray data=root.getJSONArray("data");JSONArray ar=data.getJSONObject(0).getJSONArray("ayahs");JSONArray tg=data.length()>1?data.getJSONObject(1).getJSONArray("ayahs"):new JSONArray();runOnUiThread(()->{p.setVisibility(View.GONE);info.setText(tajik?"Манбаъ: AlQuran Cloud • тарҷума: Абдолмуҳаммад Оятӣ":"Источник: AlQuran Cloud • перевод: Эльмир Кулиев");for(int i=0;i<ar.length();i++)try{JSONObject a=ar.getJSONObject(i);String tr=tg.length()>i?tg.getJSONObject(i).optString("text","Перевод недоступен"): "Перевод недоступен";LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(D(14),D(10),D(14),D(10));box.setBackgroundColor(Color.rgb(13,24,39));TextView aa=T(a.optString("text"),23,Color.rgb(247,239,216),false);aa.setGravity(Gravity.RIGHT);aa.setTextDirection(View.TEXT_DIRECTION_RTL);box.addView(aa);box.addView(T("﴾ "+a.optInt("numberInSurah")+" ﴿",12,Color.rgb(100,192,171),true));box.addView(T(tr,15,Color.rgb(190,201,214),false));add(g,box,0); }catch(Exception e){} });}catch(Exception e){runOnUiThread(()->{p.setVisibility(View.GONE);info.setText("tg".equals(LanguageManager.getLanguage(this))?"Сура бор нашуд. Интернетро санҷида, боз кӯшиш кунед.":"Не удалось загрузить эту суру. Проверь интернет и повтори.");});}}).start();}
 String get(String u)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setRequestMethod("GET");BufferedReader b=new BufferedReader(new InputStreamReader(c.getInputStream(),"UTF-8"));StringBuilder s=new StringBuilder();String x;while((x=b.readLine())!=null)s.append(x);b.close();return s.toString();}
 void prayer(){boolean tg="tg".equals(LanguageManager.getLanguage(this));LinearLayout r=page(tg?"Вақти намоз":"Время намаза");ScrollView s=new ScrollView(this);LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);g.setPadding(D(16),0,D(16),D(24));g.addView(T(tg?"Вақт аз рӯи координатҳои телефон ва минтақаи вақт ҳисоб мешавад.":"Время рассчитывается по координатам телефона и часовому поясу устройства.",13,Color.rgb(160,178,198),false));Calendar c=Calendar.getInstance();for(PrayerTime x:PrayerCalculator.calculate(PrayerSettings.latitude(this),PrayerSettings.longitude(this),c,TimeZone.getDefault(),PrayerSettings.method(this),PrayerSettings.school(this)))add(g,card(tg?new String[]{"Бомдод","Пешин","Аср","Шом","Хуфтан"}[Math.min(4,Math.max(0,Arrays.asList("Fajr","Dhuhr","Asr","Maghrib","Isha").indexOf(x.name())))]:x.name(),x.time()+"  •  "+(tg?"огоҳинома":"уведомление")),72);g.addView(T(tg?"Усул: MWL • мазҳаби Аср: Ҳанафӣ":"Метод: MWL • мазхаб Аср: Hanafi",13,Color.rgb(130,150,170),false));s.addView(g);r.addView(s,new LinearLayout.LayoutParams(-1,0,1));setContentView(r);}
